const $=id=>document.getElementById(id);
const inventory=$('cars-grid'),authDialog=$('auth-dialog'),listingDialog=$('listing-dialog');
const photoField=document.querySelector('#listing-form input[name="image"]');photoField.type='file';photoField.accept='image/jpeg,image/png,image/webp';photoField.closest('label').firstChild.textContent='Fotos do veículo';photoField.parentElement.querySelector('small').textContent='JPG, PNG ou WebP · até 4 MB';
let seller=null,authMode='register',cars=[];const storefrontId=new URLSearchParams(location.search).get('vendedor');
const currency=new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0});
const number=new Intl.NumberFormat('pt-BR');
const brandField=document.querySelector('#listing-form [name="make"]'),modelField=document.querySelector('#listing-form [name="model"]'),brandOptions=$('car-brands'),modelOptions=$('car-models');let vehicleBrands=[];const modelCache=new Map();
const normalizeName=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR').replace(/[^a-z0-9]/g,'');
async function loadVehicleBrands(){const fallback=['Acura','Audi','BMW','BYD','Chevrolet','Chery','Citroën','Fiat','Ford','GWM','Honda','Hyundai','Jeep','Kia','Land Rover','Mercedes-Benz','Mitsubishi','Nissan','Peugeot','Renault','Subaru','Toyota','Volkswagen','Volvo'];try{const response=await fetch('https://brasilapi.com.br/api/fipe/marcas/v1/carros');if(!response.ok)throw new Error('Catálogo indisponível');vehicleBrands=await response.json();if(!Array.isArray(vehicleBrands))throw new Error('Catálogo inválido');}catch{vehicleBrands=fallback.map(nome=>({nome,valor:''}));}brandOptions.innerHTML=vehicleBrands.map(item=>`<option value="${escapeAttr(item.nome)}"></option>`).join('');}
brandField.addEventListener('change',async()=>{const typed=normalizeName(brandField.value);const selected=vehicleBrands.find(item=>normalizeName(item.nome)===typed)||vehicleBrands.find(item=>typed&&normalizeName(item.nome).includes(typed));modelOptions.replaceChildren();if(!selected?.valor)return;const code=String(selected.valor);let models=modelCache.get(code);if(!models){try{const response=await fetch(`https://brasilapi.com.br/api/fipe/veiculos/v1/carros/${encodeURIComponent(code)}`);if(!response.ok)throw new Error('Modelos indisponíveis');models=await response.json();if(!Array.isArray(models))throw new Error('Modelos inválidos');modelCache.set(code,models);}catch{return;}}modelOptions.innerHTML=models.map(item=>`<option value="${escapeAttr(item.modelo)}"></option>`).join('');});
loadVehicleBrands();
function message(id,text,error=false){const node=$(id);node.textContent=text;node.classList.toggle('error',error);}
function cardHTML(car,own=false){const photo=car.image?`<img loading="lazy" src="/media/${encodeURIComponent(car.image)}" alt="${escapeHTML(car.make+' '+car.model)}" onerror="this.hidden=true;this.parentElement.classList.add('no-photo')">`:'';return `<article class="car-card"><div class="car-photo ${car.image?'':'no-photo'}">${photo}<span class="car-condition">${car.year} · ${number.format(car.mileage)} km</span></div><div class="car-card-copy"><span class="car-loc">${escapeHTML(car.location||'Brasil')} <i>·</i> ${escapeHTML(car.sellerName||'')}</span><h3>${escapeHTML(car.make)} <span>${escapeHTML(car.model)}</span></h3><p class="car-description">${escapeHTML(car.description||'Consulte mais detalhes com o vendedor.')}</p><div class="car-offer"><strong>${currency.format(car.price/100)}</strong><a class="interest-link" target="_blank" rel="noopener noreferrer" href="https://wa.me/${escapeAttr(car.whatsapp)}?text=${encodeURIComponent('Olá! Vi o anúncio do '+car.make+' '+car.model+' na Vértice Motors e gostaria de mais informações.')}" aria-label="Falar com vendedor sobre ${escapeAttr(car.make+' '+car.model)}">${own?'Falar no WhatsApp ↗':'Tenho interesse ↗'}</a></div>${own?`<button type="button" class="delete-listing" data-remove="${escapeAttr(car.id)}">Remover anúncio</button>`:''}</div></article>`;}
function escapeHTML(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
const escapeAttr=escapeHTML;
function renderInventory(){const query=$('search-query').value.trim().toLocaleLowerCase('pt-BR'),make=$('filter-make').value,sort=$('sort-price').value;let shown=cars.filter(car=>(!storefrontId||car.sellerId===storefrontId)&&(!make||car.make===make)&&(!query||`${car.make} ${car.model} ${car.location}`.toLocaleLowerCase('pt-BR').includes(query)));if(sort==='low')shown.sort((a,b)=>a.price-b.price);if(sort==='high')shown.sort((a,b)=>b.price-a.price);inventory.innerHTML=shown.map(c=>cardHTML(c)).join('');const storefront=storefrontId?cars.find(c=>c.sellerId===storefrontId):null;$('inventory-title').textContent=storefront?`Carros de ${storefront.sellerName}`:'Carros para ir mais longe.';$('inventory-copy').textContent=storefront?'Fale diretamente com o vendedor pelo WhatsApp em cada anúncio.':'Escolha com calma. Encontre o seu próximo caminho.';$('search-form').hidden=!!storefrontId;$('empty-stock').hidden=shown.length>0;$('stock-count').textContent=`${cars.length} ${cars.length===1?'carro disponível':'carros disponíveis'}`;const prior=make;$('filter-make').innerHTML='<option value="">Todas as marcas</option>'+[...new Set(cars.map(c=>c.make))].sort().map(m=>`<option value="${escapeAttr(m)}">${escapeHTML(m)}</option>`).join('');$('filter-make').value=prior;}
function renderSeller(){if(!seller){$('seller-panel').hidden=true;return;}$('seller-panel').hidden=false;$('seller-welcome').textContent=`Olá, ${seller.displayName}.`;$('share-store').onclick=async()=>{const link=new URL(location.href);link.search='';link.searchParams.set('vendedor',seller.id);link.hash='estoque';try{await navigator.clipboard.writeText(link.href);$('share-message').textContent='Link da sua loja copiado!';}catch{$('share-message').textContent=link.href;}};$('seller-listings').innerHTML=cars.filter(c=>c.sellerId===seller.id).map(c=>cardHTML(c,true)).join('')||'<p class="my-empty">Você ainda não publicou nenhum carro.</p>';document.querySelectorAll('[data-remove]').forEach(btn=>btn.addEventListener('click',()=>removeListing(btn.dataset.remove)));}
async function api(path,options={}){const multipart=options.body instanceof FormData;const response=await fetch('/api/'+path,{credentials:'same-origin',...options,headers:{...(options.body&&!multipart?{'content-type':'application/json'}:{}),...options.headers}});const result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.error||'Não foi possível concluir.');return result;}
async function load(){const [inventoryResult,sessionResult]=await Promise.allSettled([api('listings'),api('session')]);if(inventoryResult.status==='fulfilled'){cars=inventoryResult.value.listings||[];renderInventory();}else{$('empty-stock').hidden=false;$('empty-stock').querySelector('h3').textContent='Não foi possível carregar os anúncios.';$('empty-stock').querySelector('p').textContent='Tente novamente em instantes.';}if(sessionResult.status==='fulfilled'){seller=sessionResult.value.seller;renderSeller();}else seller=null;}
function showAuth(mode='register'){authMode=mode;$('seller-name').closest('label').hidden=mode==='login';$('seller-name').required=mode==='register';$('seller-password').autocomplete=mode==='login'?'current-password':'new-password';$('auth-title').textContent=mode==='login'?'Bem-vindo de volta.':'Anuncie com a Vértice.';$('auth-copy').textContent=mode==='login'?'Entre para gerenciar seus anúncios.':'Crie sua conta de vendedor gratuita.';$('auth-submit').innerHTML=mode==='login'?'Entrar <span>↗</span>':'Criar conta <span>↗</span>';$('auth-toggle').textContent=mode==='login'?'Criar uma nova conta':'Já tenho uma conta. Entrar';message('auth-message','');authDialog.showModal();}
async function removeListing(id){if(!confirm('Remover este anúncio do estoque?'))return;try{await api(`listings/${encodeURIComponent(id)}`,{method:'DELETE'});await load();}catch(error){message('auth-message',error.message,true);}}
$('seller-login').addEventListener('click',()=>showAuth(seller?'login':'register'));
$('empty-login').addEventListener('click',()=>showAuth());
$('auth-toggle').addEventListener('click',()=>showAuth(authMode==='register'?'login':'register'));
$('auth-form').addEventListener('submit',async event=>{event.preventDefault();const button=$('auth-submit');button.disabled=true;try{const input={email:$('seller-email').value,password:$('seller-password').value};if(authMode==='register')input.name=$('seller-name').value;const result=await api(authMode==='register'?'register':'login',{method:'POST',body:JSON.stringify(input)});seller=result.seller;authDialog.close();await load();$('seller-panel').scrollIntoView({behavior:'smooth',block:'start'});}catch(error){message('auth-message',error.message,true);}finally{button.disabled=false;}});
$('seller-logout').addEventListener('click',async()=>{try{await api('logout',{method:'POST'});seller=null;await load();}catch(error){message('auth-message',error.message,true);}});
$('add-listing').addEventListener('click',()=>{if(!seller)return showAuth();$('listing-form').reset();message('listing-message','');listingDialog.showModal();});
$('listing-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;const raw=Object.fromEntries(new FormData(form));const body={...raw,image:null,year:Number(raw.year),mileage:Number(raw.mileage),price:Math.round(Number(raw.price.replace(/\./g,'').replace(',','.'))*100)};try{const photo=photoField.files?.[0];if(photo){const data=new FormData();data.append('file',photo);body.image=(await api('images',{method:'POST',body:data})).key;}await api('listings',{method:'POST',body:JSON.stringify(body)});listingDialog.close();await load();$('seller-panel').scrollIntoView({behavior:'smooth',block:'start'});}catch(error){message('listing-message',error.message,true);}});
$('search-query').addEventListener('input',renderInventory);$('filter-make').addEventListener('change',renderInventory);$('sort-price').addEventListener('change',renderInventory);$('search-form').addEventListener('submit',event=>{event.preventDefault();renderInventory();});
load().then(()=>{if(storefrontId){$('hero-title').innerHTML='A loja de carros<br><em>que você procura.</em>';document.querySelector('.edition strong').innerHTML='Ver estoque <i>↘</i>';}});
